func FirstUnique(values []string) (string, bool) {
	if values == nil {
		return "", false
	}

	count := make(map[string]int)
	for _, v := range values {
		count[v]++
	}

	for _, v := range values {
		if count[v] == 1 {
			return v, true
		}
	}

	return "", false
}

